305	fn filter_client_request_ts_contents(mut content: String, experimental_methods: &[&str]) -> String {
306	    let Some((prefix, body, suffix)) = split_type_alias(&content) else {
307	        return content;
308	    };
309	    let experimental_methods: HashSet<&str> = experimental_methods
310	        .iter()
311	        .copied()
312	        .filter(|method| !method.is_empty())
313	        .collect();
314	    let arms = split_top_level(&body, '|');
315	    let filtered_arms: Vec<String> = arms
316	        .into_iter()
317	        .filter(|arm| {
318	            extract_method_from_arm(arm)
319	                .is_none_or(|method| !experimental_methods.contains(method.as_str()))
320	        })
321	        .collect();
322	    let new_body = filtered_arms.join(" | ");
323	    content = format!("{prefix}{new_body}{suffix}");
324	    let import_usage_scope = split_type_alias(&content)
325	        .map(|(_, filtered_body, _)| filtered_body)
326	        .unwrap_or_else(|| new_body.clone());
327	    prune_unused_type_imports(content, &import_usage_scope)
328	}
