389	    let suffix = &content[close_brace..];
390	    content = format!("{prefix}{new_inner}{suffix}");
391	    let import_usage_scope = split_type_alias(&content)
392	        .map(|(_, body, _)| body)
393	        .unwrap_or_else(|| new_inner.clone());
394	    prune_unused_type_imports(content, &import_usage_scope)
