125	    let bytes =
126	        std::fs::read(path).with_context(|| format!("failed to read {}", path.display()))?;
127	    if path.extension().is_some_and(|ext| ext == "json") {
128	        let value: Value = serde_json::from_slice(&bytes)
129	            .with_context(|| format!("failed to parse JSON in {}", path.display()))?;
