137	        // fixture test is platform-independent.
138	        let text = String::from_utf8(bytes)
139	            .with_context(|| format!("expected UTF-8 TypeScript in {}", path.display()))?;
140	        let text = text.replace("\r\n", "\n").replace('\r', "\n");
