152	fn canonicalize_json(value: &Value) -> Value {
153	    match value {
154	        Value::Array(items) => {
155	            // NOTE: We sort some JSON arrays to make schema fixture comparisons stable across
156	            // platforms.
157	            //
158	            // In general, JSON array ordering is significant. However, this code path is used
159	            // only by `schema_fixtures_match_generated` to compare our *vendored* JSON schema
160	            // files against freshly generated output. Some parts of schema generation end up
161	            // with non-deterministic ordering across platforms (often due to map iteration order
162	            // upstream), which can cause Windows CI failures even when the generated schema is
163	            // semantically equivalent.
164	            //
165	            // JSON Schema itself also contains a number of array-valued keywords whose ordering
166	            // does not affect validation semantics (e.g. `required`, `type`, `enum`, `anyOf`,
167	            // `oneOf`, `allOf`). That makes it reasonable to treat many schema-emitted arrays as
168	            // order-insensitive for the purpose of fixture diffs.
169	            //
170	            // To avoid accidentally changing the meaning of arrays where order *could* matter
171	            // (e.g. tuple validation / `prefixItems`-style arrays), we only sort arrays when we
172	            // can derive a stable sort key for *every* element. If we cannot, we preserve the
173	            // original ordering.
174	            let items = items.iter().map(canonicalize_json).collect::<Vec<_>>();
175	            let mut sortable = Vec::with_capacity(items.len());
176	            for item in &items {
