178	                    return Value::Array(items);
179	                };
180	                let stable = serde_json::to_string(item).unwrap_or_default();
181	                sortable.push((key, stable));
182	            }
183	
184	            let mut items = items.into_iter().zip(sortable).collect::<Vec<_>>();
185	
186	            items.sort_by(
187	                |(_, (key_left, stable_left)), (_, (key_right, stable_right))| match key_left
188	                    .cmp(key_right)
189	                {
190	                    Ordering::Equal => stable_left.cmp(stable_right),
191	                    other => other,
192	                },
193	            );
